1	package sqlite
2	
3	import (
4		"context"
5		"database/sql"
6		"strings"
7	
8		"github.com/pkg/errors"
9	
10		storepb "github.com/usememos/memos/proto/gen/store"
11		"github.com/usememos/memos/store"
12	)
13	
14	const deleteUserBatchSize = 500
15	
16	type deleteUserMemoRef struct {
17		ID  int32
18		UID string
19	}
20	
21	type deleteUserTargetSet struct {
22		memos           []deleteUserMemoRef
23		attachments     []*store.Attachment
24		attachmentIDs   []int32
25		userSettingKeys []storepb.UserSetting_Key
26		inboxIDs        []int32
27	}
28	
29	func (d *DB) DeleteUser(ctx context.Context, delete *store.DeleteUser) (*store.DeleteUserResult, error) {
30		tx, err := d.db.BeginTx(ctx, nil)
31		if err != nil {
32			return nil, errors.Wrap(err, "failed to begin delete user transaction")
33		}
34		defer func() {
35			_ = tx.Rollback()
36		}()
37	
38		targets, err := collectDeleteUserTargets(ctx, tx, delete.ID)
39		if err != nil {
40			return nil, errors.Wrap(err, "failed to collect delete user targets")
41		}
42	
43		if err := deleteUserTargetsTx(ctx, tx, delete.ID, targets); err != nil {
44			return nil, errors.Wrap(err, "failed to delete user targets")
45		}
46	
47		if store.GetDeleteUserFailpoint(ctx) == store.DeleteUserFailpointBeforeCommit {
48			return nil, errors.New("delete user failpoint before commit")
49		}
50	
51		if err := tx.Commit(); err != nil {
52			return nil, errors.Wrap(err, "failed to commit delete user transaction")
53		}
54	
55		return &store.DeleteUserResult{
56			Attachments:     targets.attachments,
57			UserSettingKeys: targets.userSettingKeys,
58		}, nil
59	}
60	
61	func collectDeleteUserTargets(ctx context.Context, tx *sql.Tx, userID int32) (*deleteUserTargetSet, error) {
62		targets := &deleteUserTargetSet{}
63	
64		memos, err := listDeleteUserMemoTree(ctx, tx, userID)
65		if err != nil {
66			return nil, err
67		}
68		targets.memos = memos
69	
70		attachments, err := listDeleteUserAttachments(ctx, tx, userID, memoIDsFromRefs(memos))
71		if err != nil {
72			return nil, err
73		}
74		targets.attachments = attachments
75		targets.attachmentIDs = attachmentIDsFromList(attachments)
76	
77		userSettingKeys, err := listDeleteUserSettingKeys(ctx, tx, userID)
78		if err != nil {
79			return nil, err
80		}
81		targets.userSettingKeys = userSettingKeys
82	
83		inboxIDs, err := listDeleteUserInboxIDs(ctx, tx, userID, memoIDSetFromRefs(memos))
84		if err != nil {
85			return nil, err
86		}
87		targets.inboxIDs = inboxIDs
88	
89		return targets, nil
90	}
91	
92	func deleteUserTargetsTx(ctx context.Context, tx *sql.Tx, userID int32, targets *deleteUserTargetSet) error {
93		memoIDs := memoIDsFromRefs(targets.memos)
94		contentIDs := memoContentIDsFromRefs(targets.memos)
95	
96		if err := deleteReactionsByContentIDsTx(ctx, tx, contentIDs); err != nil {
97			return err
98		}
99		if err := deleteAttachmentsByIDsTx(ctx, tx, targets.attachmentIDs); err != nil {
100			return err
101		}
102		if err := deleteReactionsByCreatorTx(ctx, tx, userID); err != nil {
103			return err
104		}
105		if err := deleteMemoSharesTx(ctx, tx, userID, memoIDs); err != nil {
106			return err
107		}
108		if err := deleteInboxesByIDsTx(ctx, tx, targets.inboxIDs); err != nil {
109			return err
110		}
111		if err := deleteUserIdentitiesTx(ctx, tx, userID); err != nil {
112			return err
113		}
114		if err := deleteUserSettingsTx(ctx, tx, userID); err != nil {
115			return err
116		}
117		if err := deleteMemoRelationsTx(ctx, tx, memoIDs); err != nil {
118			return err
119		}
120		if err := deleteMemosTx(ctx, tx, memoIDs); err != nil {
121			return err
122		}
123		if err := deleteUserRowTx(ctx, tx, userID); err != nil {
124			return err
125		}
126		return nil
127	}
128	
129	func listDeleteUserMemoTree(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
130		return listDeleteUserMemoTreeRecursive(ctx, tx, userID)
131	}
132	
133	func listDeleteUserMemoTreeRecursive(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
134		rows, err := tx.QueryContext(ctx, `
135			WITH RECURSIVE memo_tree(id, uid) AS (
136				SELECT id, uid
137				FROM memo
138				WHERE creator_id = `+deleteUserPlaceholder(1)+`
139				UNION
140				SELECT child.id, child.uid
141				FROM memo child
142				JOIN memo_relation rel ON rel.memo_id = child.id AND rel.type = 'COMMENT'
143				JOIN memo_tree parent ON rel.related_memo_id = parent.id
144			)
145			SELECT id, uid
146			FROM memo_tree
147		`, userID)
148		if err != nil {
149			return nil, err
150		}
151		defer rows.Close()
152	
153		memos := make([]deleteUserMemoRef, 0)
154		for rows.Next() {
155			var memo deleteUserMemoRef
156			if err := rows.Scan(&memo.ID, &memo.UID); err != nil {
157				return nil, err
158			}
159			memos = append(memos, memo)
160		}
161		if err := rows.Err(); err != nil {
162			return nil, err
163		}
164	
165		return memos, nil
166	}
167	
168	func listDeleteUserAttachments(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) ([]*store.Attachment, error) {
169		attachments := make([]*store.Attachment, 0)
170		seen := make(map[int32]struct{})
171		if err := appendDeleteUserAttachments(ctx, tx, `
172			SELECT
173				id,
174				uid,
175				creator_id,
176				memo_id,
177				storage_type,
178				reference,
179				payload
180			FROM attachment
181			WHERE creator_id = `+deleteUserPlaceholder(1), []any{userID}, seen, &attachments); err != nil {
182			return nil, err
183		}
184	
185		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
186			clause, args := deleteUserInClause(1, batch)
187			if err := appendDeleteUserAttachments(ctx, tx, `
188				SELECT
189					id,
190					uid,
191					creator_id,
192					memo_id,
193					storage_type,
194					reference,
195					payload
196				FROM attachment
197				WHERE memo_id IN `+clause, args, seen, &attachments); err != nil {
198				return nil, err
199			}
200		}
201	
202		return attachments, nil
203	}
204	
205	func appendDeleteUserAttachments(ctx context.Context, tx *sql.Tx, query string, args []any, seen map[int32]struct{}, attachments *[]*store.Attachment) error {
206		rows, err := tx.QueryContext(ctx, query, args...)
207		if err != nil {
208			return err
209		}
210		defer rows.Close()
211	
212		for rows.Next() {
213			attachment := &store.Attachment{}
214			var memoID sql.NullInt32
215			var storageType string
216			var payloadBytes []byte
217			if err := rows.Scan(&attachment.ID, &attachment.UID, &attachment.CreatorID, &memoID, &storageType, &attachment.Reference, &payloadBytes); err != nil {
218				return err
219			}
220			if _, exists := seen[attachment.ID]; exists {
221				continue
222			}
223			seen[attachment.ID] = struct{}{}
224			if memoID.Valid {
225				attachment.MemoID = &memoID.Int32
226			}
227			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
228			payload := &storepb.AttachmentPayload{}
229			if len(payloadBytes) > 0 {
230				if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
231					return err
232				}
233			}
234			attachment.Payload = payload
235			*attachments = append(*attachments, attachment)
236		}
237		return rows.Err()
238	}
239	
240	func listDeleteUserSettingKeys(ctx context.Context, tx *sql.Tx, userID int32) ([]storepb.UserSetting_Key, error) {
241		rows, err := tx.QueryContext(ctx, deleteUserSettingKeysQuery(), userID)
242		if err != nil {
243			return nil, err
244		}
245		defer rows.Close()
246	
247		keys := make([]storepb.UserSetting_Key, 0)
248		for rows.Next() {
249			var keyString string
250			if err := rows.Scan(&keyString); err != nil {
251				return nil, err
252			}
253			key := storepb.UserSetting_Key(storepb.UserSetting_Key_value[keyString])
254			keys = append(keys, key)
255		}
256		if err := rows.Err(); err != nil {
257			return nil, err
258		}
259	
260		return keys, nil
261	}
262	
263	func deleteUserSettingKeysQuery() string {
264		return `SELECT key FROM user_setting WHERE user_id = ` + deleteUserPlaceholder(1)
265	}
266	
267	func listDeleteUserInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
268		directIDs, err := listDeleteUserDirectInboxIDs(ctx, tx, userID)
269		if err != nil {
270			return nil, err
271		}
272		inboxIDs := append([]int32{}, directIDs...)
273		if len(memoIDSet) == 0 {
274			return inboxIDs, nil
275		}
276	
277		memoIDs, err := listDeleteUserMemoReferencedInboxIDs(ctx, tx, userID, memoIDSet)
278		if err != nil {
279			return nil, err
280		}
281		return append(inboxIDs, memoIDs...), nil
282	}
283	
284	func listDeleteUserDirectInboxIDs(ctx context.Context, tx *sql.Tx, userID int32) ([]int32, error) {
285		rows, err := tx.QueryContext(ctx, `
286			SELECT id
287			FROM inbox
288			WHERE sender_id = `+deleteUserPlaceholder(1)+`
289				OR receiver_id = `+deleteUserPlaceholder(2), userID, userID)
290		if err != nil {
291			return nil, err
292		}
293		defer rows.Close()
294	
295		inboxIDs := make([]int32, 0)
296		for rows.Next() {
297			var inboxID int32
298			if err := rows.Scan(&inboxID); err != nil {
299				return nil, err
300			}
301			inboxIDs = append(inboxIDs, inboxID)
302		}
303		if err := rows.Err(); err != nil {
304			return nil, err
305		}
306	
307		return inboxIDs, nil
308	}
309	
310	func listDeleteUserMemoReferencedInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
311		rows, err := tx.QueryContext(ctx, `
312			SELECT id, message
313			FROM inbox
314			WHERE sender_id <> `+deleteUserPlaceholder(1)+`
315				AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
316		if err != nil {
317			return nil, err
318		}
319		defer rows.Close()
320	
321		inboxIDs := make([]int32, 0)
322		for rows.Next() {
323			var (
324				inboxID    int32
325				messageRaw []byte
326			)
327			if err := rows.Scan(&inboxID, &messageRaw); err != nil {
328				return nil, err
329			}
330			if len(messageRaw) == 0 {
331				continue
332			}
333	
334			message := &storepb.InboxMessage{}
335			if err := protojsonUnmarshaler.Unmarshal(messageRaw, message); err != nil {
336				return nil, err
337			}
338			if inboxMessageTouchesMemoSet(message, memoIDSet) {
339				inboxIDs = append(inboxIDs, inboxID)
340			}
341		}
342		if err := rows.Err(); err != nil {
343			return nil, err
344		}
345	
346		return inboxIDs, nil
347	}
348	
349	func inboxMessageTouchesMemoSet(message *storepb.InboxMessage, memoIDSet map[int32]struct{}) bool {
350		if message == nil {
351			return false
352		}
353	
354		switch message.Type {
355		case storepb.InboxMessage_MEMO_COMMENT:
356			payload := message.GetMemoComment()
357			if payload == nil {
358				return false
359			}
360			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
361		case storepb.InboxMessage_MEMO_MENTION:
362			payload := message.GetMemoMention()
363			if payload == nil {
364				return false
365			}
366			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
367		default:
368			return false
369		}
370	}
371	
372	func memoIDInSet(id int32, memoIDSet map[int32]struct{}) bool {
373		if id == 0 {
374			return false
375		}
376		_, exists := memoIDSet[id]
377		return exists
378	}
379	
380	func deleteReactionsByContentIDsTx(ctx context.Context, tx *sql.Tx, contentIDs []string) error {
381		for _, batch := range deleteUserBatches(contentIDs, deleteUserBatchSize) {
382			clause, args := deleteUserInClause(1, batch)
383			if _, err := tx.ExecContext(ctx, `DELETE FROM reaction WHERE content_id IN `+clause, args...); err != nil {
384				return err
385			}
386		}
387		return nil
388	}
389	
390	func deleteAttachmentsByIDsTx(ctx context.Context, tx *sql.Tx, attachmentIDs []int32) error {
391		for _, batch := range deleteUserBatches(attachmentIDs, deleteUserBatchSize) {
392			clause, args := deleteUserInClause(1, batch)
393			if _, err := tx.ExecContext(ctx, `DELETE FROM attachment WHERE id IN `+clause, args...); err != nil {
394				return err
395			}
396		}
397		return nil
398	}
399	
400	func deleteReactionsByCreatorTx(ctx context.Context, tx *sql.Tx, userID int32) error {
401		_, err := tx.ExecContext(ctx, `DELETE FROM reaction WHERE creator_id = `+deleteUserPlaceholder(1), userID)
402		return err
403	}
404	
405	func deleteMemoSharesTx(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) error {
406		if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE creator_id = `+deleteUserPlaceholder(1), userID); err != nil {
407			return err
408		}
409		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
410			clause, args := deleteUserInClause(1, batch)
411			if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE memo_id IN `+clause, args...); err != nil {
412				return err
413			}
414		}
415		return nil
416	}
417	
418	func deleteInboxesByIDsTx(ctx context.Context, tx *sql.Tx, inboxIDs []int32) error {
419		for _, batch := range deleteUserBatches(inboxIDs, deleteUserBatchSize) {
420			clause, args := deleteUserInClause(1, batch)
421			if _, err := tx.ExecContext(ctx, `DELETE FROM inbox WHERE id IN `+clause, args...); err != nil {
422				return err
423			}
424		}
425		return nil
426	}
427	
428	func deleteUserIdentitiesTx(ctx context.Context, tx *sql.Tx, userID int32) error {
429		_, err := tx.ExecContext(ctx, `DELETE FROM user_identity WHERE user_id = `+deleteUserPlaceholder(1), userID)
430		return err
431	}
432	
433	func deleteUserSettingsTx(ctx context.Context, tx *sql.Tx, userID int32) error {
434		_, err := tx.ExecContext(ctx, `DELETE FROM user_setting WHERE user_id = `+deleteUserPlaceholder(1), userID)
435		return err
436	}
437	
438	func deleteMemoRelationsTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
439		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
440			memoClause, args := deleteUserInClause(1, batch)
441			relatedClause, relatedArgs := deleteUserInClause(len(args)+1, batch)
442			query := `DELETE FROM memo_relation WHERE memo_id IN ` + memoClause + ` OR related_memo_id IN ` + relatedClause
443			args = append(args, relatedArgs...)
444			if _, err := tx.ExecContext(ctx, query, args...); err != nil {
445				return err
446			}
447		}
448		return nil
449	}
450	
451	func deleteMemosTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
452		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
453			clause, args := deleteUserInClause(1, batch)
454			if _, err := tx.ExecContext(ctx, `DELETE FROM memo WHERE id IN `+clause, args...); err != nil {
455				return err
456			}
457		}
458		return nil
459	}
460	
461	func deleteUserRowTx(ctx context.Context, tx *sql.Tx, userID int32) error {
462		_, err := tx.ExecContext(ctx, `DELETE FROM user WHERE id = `+deleteUserPlaceholder(1), userID)
463		return err
464	}
465	
466	func deleteUserPlaceholder(_ int) string {
467		return "?"
468	}
469	
470	func deleteUserInClause[T any](start int, values []T) (string, []any) {
471		placeholders := make([]string, 0, len(values))
472		args := make([]any, 0, len(values))
473		for i, value := range values {
474			placeholders = append(placeholders, deleteUserPlaceholder(start+i))
475			args = append(args, value)
476		}
477		return "(" + strings.Join(placeholders, ", ") + ")", args
478	}
479	
480	func deleteUserBatches[T any](values []T, size int) [][]T {
481		if len(values) == 0 {
482			return nil
483		}
484		if size <= 0 {
485			size = len(values)
486		}
487	
488		batches := make([][]T, 0, (len(values)+size-1)/size)
489		for start := 0; start < len(values); start += size {
490			end := min(start+size, len(values))
491			batches = append(batches, values[start:end])
492		}
493		return batches
494	}
495	
496	func memoIDsFromRefs(memos []deleteUserMemoRef) []int32 {
497		ids := make([]int32, 0, len(memos))
498		for _, memo := range memos {
499			ids = append(ids, memo.ID)
500		}
501		return ids
502	}
503	
504	func memoIDSetFromRefs(memos []deleteUserMemoRef) map[int32]struct{} {
505		idSet := make(map[int32]struct{}, len(memos))
506		for _, memo := range memos {
507			idSet[memo.ID] = struct{}{}
508		}
509		return idSet
510	}
511	
512	func memoContentIDsFromRefs(memos []deleteUserMemoRef) []string {
513		contentIDs := make([]string, 0, len(memos))
514		for _, memo := range memos {
515			contentIDs = append(contentIDs, "memos/"+memo.UID)
516		}
517		return contentIDs
518	}
519	
520	func attachmentIDsFromList(attachments []*store.Attachment) []int32 {
521		ids := make([]int32, 0, len(attachments))
522		for _, attachment := range attachments {
523			if attachment == nil {
524				continue
525			}
526			ids = append(ids, attachment.ID)
527		}
528		return ids
529	}
